def transform(grid):
    colors = {v for row in grid for v in row if v != 0}
    objects = []
    for color in colors:
        cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        tile = [[color if grid[r][c] == color else 0 for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]
        objects.append(((r0 + r1) / 2, (c0 + c1) / 2, tile))
    objects.sort(key=lambda obj: obj[1])
    row_span = max(obj[0] for obj in objects) - min(obj[0] for obj in objects)
    col_span = max(obj[1] for obj in objects) - min(obj[1] for obj in objects)
    if row_span > col_span:
        height = sum(len(obj[2]) for obj in objects)
        width = max(len(obj[2][0]) for obj in objects)
        out = [[0] * width for _ in range(height)]
        rpos = 0
        for _, _, tile in objects:
            for r in range(len(tile)):
                for c in range(len(tile[0])):
                    out[rpos + r][c] = tile[r][c]
            rpos += len(tile)
    else:
        height = max(len(obj[2]) for obj in objects)
        width = sum(len(obj[2][0]) for obj in objects)
        out = [[0] * width for _ in range(height)]
        cpos = 0
        for _, _, tile in objects:
            for r in range(len(tile)):
                for c in range(len(tile[0])):
                    out[r][cpos + c] = tile[r][c]
            cpos += len(tile[0])
    return out
